package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PoolService {

    /** A pool with its members, in the order they were added. */
    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's pools in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        return all.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** Add a pool to the sheet, the sheet created first if it was never loaded; refused (409) when
     *  the sheet has a pool of the name already. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        if (pools.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a pool of that name");
        }
        Pool pool = pools.saveAndFlush(new Pool(sheetId, name));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + name);
        return pool;
    }

    /** Add a person of the sheet to a pool with a share; refused (404) for a pool or person not on
     *  the sheet, (409) when the person is in the pool already. */
    @Transactional
    public PoolMember addMember(String sheetId, String user, String poolName, long personId, BigDecimal share) {
        sheets.lock(sheetId);
        Pool pool = pools.findBySheetIdAndNameIgnoreCase(sheetId, poolName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person is in the pool already");
        }
        PoolMember member = members.saveAndFlush(new PoolMember(pool.getId(), person.getId(), share));
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + share.setScale(2).toPlainString());
        return member;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member as the screen shows it: the person's id and their share with two decimals. */
    public record MemberView(long personId, String share) {
        static MemberView of(PoolMember m) {
            return new MemberView(m.getPersonId(), m.getShare().setScale(2).toPlainString());
        }
    }

    /** A pool as the screen shows it: its name and its members in the order they were added. */
    public record PoolView(String name, List<MemberView> members) {
        static PoolView of(PoolService.PoolWithMembers p) {
            return new PoolView(p.pool().getName(), p.members().stream().map(MemberView::of).toList());
        }
    }

    /** A pool as the form submits it: a name (not blank). */
    public record PoolForm(@NotBlank @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it: the pool, a person and a share percent with up to
     *  two decimals, more than 0.00 and at most 100.00. */
    public record MemberForm(
            @NotBlank @Size(max = 200) String pool,
            @NotNull Long personId,
            @NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String share) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(PoolView::of).toList();
    }

    /** Add a pool; resolves to the sheet's pools with it. */
    @PostMapping
    public List<PoolView> add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm body) {
        service.add(sheetId, user.trim(), body.name().trim());
        return list(sheetId, user);
    }

    /** Add a member to a pool; resolves to the sheet's pools with it. */
    @PostMapping("/members")
    public List<PoolView> addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm body) {
        service.addMember(sheetId, user.trim(), body.pool().trim(), body.personId(), share(body.share()));
        return list(sheetId, user);
    }

    /** The share, refused (400) unless more than 0.00 and at most 100.00. */
    private static BigDecimal share(String text) {
        BigDecimal share = new BigDecimal(text.trim()).setScale(2);
        if (share.signum() <= 0 || share.compareTo(new BigDecimal("100.00")) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A share is more than 0.00 and at most 100.00");
        }
        return share;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';

/** A share percent: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A person in a pool with their share percent (two decimals). */
export interface PoolMember {
  personId: number;
  share: string;
}

/** A pool on the sheet: its name and its members, in the order they were added. */
export interface Pool {
  name: string;
  members: PoolMember[];
}

@Injectable({ providedIn: 'root' })
export class PoolsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's pools, in the order they were added. */
  list(sheetId: string): Promise<Pool[]> {
    return firstValueFrom(this.http.get<Pool[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** Add a pool; resolves to the sheet's pools with it. */
  add(sheetId: string, name: string): Promise<Pool[]> {
    return firstValueFrom(this.http.post<Pool[]>(this.url(sheetId), { name }, { headers: this.headers() }));
  }

  /** Add a person to a pool with a share; resolves to the sheet's pools with them. */
  addMember(sheetId: string, pool: string, personId: number, share: string): Promise<Pool[]> {
    return firstValueFrom(
      this.http.post<Pool[]>(`${this.url(sheetId)}/members`, { pool, personId, share }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function poolError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name for the pool.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The sheet has a pool of that name already.';
  return otherError(e);
}

export function memberError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a share more than 0.00 and at most 100.00, with up to two decimals.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That person is in the pool already.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That pool or person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}
import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { cents, money } from '../claims/claims-api';
import type { Person } from '../people/people-api';
import { Pool, PoolsApi, SHARE_PATTERN, memberError, poolError } from './pools-api';

// One pool's row: its total share and whether it is balanced, its members each with their share,
// and the form that adds a member to it.
@Component({
  selector: 'li[appPoolRow]',
  imports: [ReactiveFormsModule],
  host: { '[attr.data-testid]': "'pool-row-' + pool().name" },
  template: `
      <h3 data-testid="pool-name">{{ pool().name }}</h3>
      <p>Total share <strong data-testid="pool-total-share">{{ totalShare() }}</strong>
        Balanced <strong data-testid="pool-balanced">{{ balanced() ? 'yes' : 'no' }}</strong></p>
      <ul [attr.aria-label]="'Members of pool ' + pool().name">
        @for (m of pool().members; track m.personId) {
          <li [attr.data-testid]="'pool-member-' + pool().name + '-' + m.personId">
            <span data-testid="pool-member-name">{{ nameOf(m.personId) }}</span>
            <span data-testid="pool-share">{{ m.share }}</span>
            @if (retired(m.personId)) {
              <span>(retired)</span>
            }
          </li>
        }
      </ul>
      <form [formGroup]="form" (ngSubmit)="add()" [attr.aria-label]="'Add a member to pool ' + pool().name">
        <label [for]="'pool-member-select-' + pool().name">Person</label>
        <select [id]="'pool-member-select-' + pool().name" data-testid="pool-member-select" formControlName="personId">
          <option value="">Choose a person</option>
          @for (p of people(); track p.id) {
            <option [value]="p.id">{{ p.name }}</option>
          }
        </select>
        <label [for]="'pool-member-share-' + pool().name">Share %</label>
        <input [id]="'pool-member-share-' + pool().name" data-testid="pool-member-share" formControlName="share"
          inputmode="decimal" autocomplete="off" />
        <button type="submit" data-testid="pool-member-add">Add member</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-error">{{ err }}</p>
        }
      </form>
  `,
})
export class PoolRow {
  private readonly session = inject(Session);
  private readonly api = inject(PoolsApi);

  readonly pool = input.required<Pool>();
  /** The people on the sheet (retired ones too). */
  readonly people = input.required<Person[]>();
  /** The sheet's pools after a member was added. */
  readonly saved = output<Pool[]>();

  protected readonly error = signal<string | null>(null);
  private saving = false;

  protected readonly form = new FormGroup({
    personId: new FormControl('', { nonNullable: true }),
    share: new FormControl('', { nonNullable: true }),
  });

  private readonly byId = computed(() => new Map(this.people().map((p) => [p.id, p])));
  /** The members' shares added up, a retired member's (any with a retirement date) counting 0.00. */
  private readonly totalCents = computed(() =>
    this.pool().members.reduce((sum, m) => sum + (this.retired(m.personId) ? 0 : cents(m.share)), 0));
  protected readonly totalShare = computed(() => money(this.totalCents()));
  /** Balanced when the shares total exactly 100.00. */
  protected readonly balanced = computed(() => this.totalCents() === 10000);

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  protected nameOf(personId: number): string {
    return this.byId().get(personId)?.name ?? '';
  }

  protected retired(personId: number): boolean {
    return (this.byId().get(personId)?.retiredFrom ?? null) !== null;
  }

  protected async add(): Promise<void> {
    if (this.saving) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    const personId = Number(value.personId);
    const share = value.share.trim();
    if (value.personId === '' || !this.byId().has(personId)) {
      this.error.set('Choose a person to add to the pool.');
      return;
    }
    if (this.pool().members.some((m) => m.personId === personId)) {
      this.error.set('That person is in the pool already.');
      return;
    }
    if (!SHARE_PATTERN.test(share) || cents(share) <= 0 || cents(share) > 10000) {
      this.error.set('Enter a share more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    this.saving = true;
    try {
      const pools = await this.api.addMember(sheetId, this.pool().name, personId, share);
      if (this.session.sheetId() === sheetId) this.saved.emit(pools);
      this.form.reset({ personId: '', share: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(memberError(e));
    } finally {
      this.saving = false;
    }
  }
}

// The sheet's pools, in the order they were added, and the form that adds one.
@Component({
  selector: 'app-pools',
  imports: [ReactiveFormsModule, PoolRow],
  template: `
    <section aria-labelledby="pools-heading">
      <h2 id="pools-heading">Pools</h2>
      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a pool">
        <label for="pool-form-name">Name</label>
        <input id="pool-form-name" data-testid="pool-form-name" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
      <ul aria-label="Pools" data-testid="pools-list">
        @for (p of pools(); track p.name) {
          <li appPoolRow [pool]="p" [people]="people()" (saved)="taken($event)"></li>
        }
      </ul>
    </section>
  `,
})
export class Pools {
  private readonly session = inject(Session);
  private readonly api = inject(PoolsApi);

  /** The people on the sheet (retired ones too). */
  readonly people = input.required<Person[]>();

  protected readonly pools = signal<Pool[]>([]);
  protected readonly error = signal<string | null>(null);
  private saving = false;
  /** Guards against a slower, older read landing over a newer one. */
  private readSeq = 0;

  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.pools.set([]);
        this.error.set(null);
        this.form.reset({ name: '' }, { emitEvent: false });
        if (id) void this.read(id);
      });
    });
  }

  protected taken(pools: Pool[]): void {
    this.readSeq++;
    this.pools.set(pools);
  }

  protected async add(): Promise<void> {
    if (this.saving) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const name = this.form.getRawValue().name.trim();
    if (name === '') {
      this.error.set('Enter a name for the pool.');
      return;
    }
    if (this.pools().some((p) => p.name.toLowerCase() === name.toLowerCase())) {
      this.error.set('The sheet has a pool of that name already.');
      return;
    }
    this.saving = true;
    try {
      const pools = await this.api.add(sheetId, name);
      if (this.session.sheetId() === sheetId) this.taken(pools);
      this.form.reset({ name: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(poolError(e));
    } finally {
      this.saving = false;
    }
  }

  private async read(sheetId: string): Promise<void> {
    const seq = ++this.readSeq;
    try {
      const pools = await this.api.list(sheetId);
      if (seq === this.readSeq && this.session.sheetId() === sheetId) this.pools.set(pools);
    } catch {
      if (seq === this.readSeq) this.error.set('Something went wrong loading pools; try again.');
    }
  }
}

